command:
task_dir=${RUN_ROOT}/trace_preflight; mkdir -p ${task_dir}; python3 tools/distributed-trace-scheduler/scripts/preflight_gem5_runtime.py --server-list ${SERVERS} --gem5 ${GEM5_BIN} --out-ok ${RUN_ROOT}/trace/preflight/servers.ok.txt --out-tsv ${RUN_ROOT}/trace/preflight/preflight.tsv > ${task_dir}/log.txt 2>&1 && test -s ${RUN_ROOT}/trace/preflight/servers.ok.txt && printf '{"status":"passed"}
' > ${task_dir}/status.json || printf '{"status":"failed"}
' > ${task_dir}/status.json; printf 'trace preflight complete
' > ${task_dir}/summary.txt

task_dir=${RUN_ROOT}/fs_dry_run; mkdir -p ${task_dir}; python3 ~/.codex/skills/local/gem5-fs-checkpoint-batch-regression/scripts/fs_checkpoint_batch.py run --workload-list ${FS_WORKLOAD_LIST} --checkpoint-root ${FS_CHECKPOINT_ROOT} --arch-script ${VALIDATION_DIR}/scripts/run_fs_checkpoint.sh --tag ${FS_TAG} --work-root ${RUN_ROOT}/fs --jobs ${FS_JOBS:-12} --dry-run > ${task_dir}/log.txt 2>&1 && printf '{"status":"passed"}
' > ${task_dir}/status.json || printf '{"status":"failed"}
' > ${task_dir}/status.json; printf 'fs batch dry-run complete
' > ${task_dir}/summary.txt

task_dir=${RUN_ROOT}/fs_spec_target12; mkdir -p ${task_dir}; python3 ~/.codex/skills/local/gem5-fs-checkpoint-batch-regression/scripts/fs_checkpoint_batch.py run --workload-list ${FS_WORKLOAD_LIST} --checkpoint-root ${FS_CHECKPOINT_ROOT} --arch-script ${VALIDATION_DIR}/scripts/run_fs_checkpoint.sh --tag ${FS_TAG} --work-root ${RUN_ROOT}/fs --jobs ${FS_JOBS:-12} > ${task_dir}/log.txt 2>&1; python3 ~/.codex/skills/local/gem5-fs-checkpoint-batch-regression/scripts/fs_checkpoint_batch.py status --tag ${FS_TAG} --work-root ${RUN_ROOT}/fs >> ${task_dir}/log.txt 2>&1; if rg -q 'completed=12 abort=0 running=0 pending=0' ${task_dir}/log.txt; then printf '{"status":"passed"}
' > ${task_dir}/status.json; else printf '{"status":"failed"}
' > ${task_dir}/status.json; fi; printf 'parallel FS target batch finished
' > ${task_dir}/summary.txt

task_dir=${RUN_ROOT}/final_verify; mkdir -p ${task_dir}; python3 ${VALIDATION_DIR}/scripts/summarize_regression.py --run-root ${RUN_ROOT} --fs-root ${RUN_ROOT}/fs/${FS_TAG} --trace-root ${RUN_ROOT}/trace/${TRACE_TAG} --expected-fs 12 --expected-trace 66 --task setup_env --task trace_preflight --task fs_dry_run --task fs_spec_target12 --task trace_top66 --out-final-status ${RUN_ROOT}/final_status.csv --out-report ${RUN_ROOT}/final_report.md > ${task_dir}/log.txt 2>&1 && printf '{"status":"passed"}
' > ${task_dir}/status.json || printf '{"status":"failed"}
' > ${task_dir}/status.json; printf 'final aggregation complete
' > ${task_dir}/summary.txt
